export const createReleaseReadinessPlan = (
  workspaceRoot: string
): readonly ReleaseCheck[] => [
  new ReleaseCheck({
    args: ["run", "verification"],
    command: "bun",
    cwd: workspaceRoot,
    id: "verification",
    label: "Canonical repository verification",
  }),
  new ReleaseCheck({
    args: ["run", "test"],
    command: "bun",
    cwd: workspaceRoot,
    id: "test",
    label: "Workspace tests including the direct calculator journey",
  }),
  new ReleaseCheck({
    args: ["run", "build"],
    command: "bun",
    cwd: workspaceRoot,
    id: "build",
    label: "Workspace production builds",
  }),
  new ReleaseCheck({
    args: ["run", "docs:validate"],
    command: "bun",
    cwd: workspaceRoot,
    id: "docs-validation",
    label: "Documentation content validation",
  }),
  new ReleaseCheck({
    args: ["run", "sdk:check-packed-artifact"],
    command: "bun",
    cwd: workspaceRoot,
    id: "packed-artifact",
    label: "Focused SDK packed artifact proof",
  }),
  new ReleaseCheck({
    args: ["run", "sdk:validate-downstream"],
    command: "bun",
    cwd: workspaceRoot,
    id: "downstream-consumer",
    label: "Strict downstream package proof",
  }),
  new ReleaseCheck({
    args: ["run", "api:smoke"],
    command: "bun",
    cwd: workspaceRoot,
    id: "api-smoke",
    label: "Public API smoke evidence",
  }),
  new ReleaseCheck({
    args: ["run", "web:test:native-pair"],
    command: "bun",
    cwd: workspaceRoot,
    id: "docs-browser",
    label: "Built native Website and documentation evidence",
  }),
  new ReleaseCheck({
    args: ["run", "changeset:status"],
    command: "bun",
    cwd: workspaceRoot,
    id: "changeset-status",
    label: "Pending release train status",
  }),
];

/** @deprecated Use `createReleaseReadinessPlan`. */
export const makeReleaseReadinessPlan = (workspaceRoot: string) =>
  createReleaseReadinessPlan(workspaceRoot);

export const renderReleaseReadinessReport = (
  report: ReleaseReadinessReport | CiReleaseReadinessReport
): string =>
  Array.prepend(
    Array.map(
      report.outcomes,
      (outcome) =>
        `PASS [${outcome.check.id}] target=${outcome.check.label}; stdout=${outcome.stdoutDetail?.path ?? "none"} (${outcome.stdoutDetail?.sha256 ?? "unavailable"}); stderr=${outcome.stderrDetail?.path ?? "none"} (${outcome.stderrDetail?.sha256 ?? "unavailable"})`
    ),
    Match.value(report).pipe(
      Match.tag(
        "ReleaseReadinessReport",
        (value) =>
          `Release readiness passed ${value.outcomes.length} ordered checks once; postcondition=local candidate checks passed; nonclaim=no publication, tag, release, deployment or provider mutation.`
      ),
      Match.tag(
        "CiReleaseReadinessReport",
        (value) =>
          `CI release graph passed ${value.outcomes.length} ordered checks; postcondition=repository checks passed for this CI revision; nonclaim=no candidate, attempt receipt, publication, tag, release, deployment or provider mutation.`
      ),
      Match.exhaustive
    )
  ).join("\n");
