31	    ];
32	    const recordTargets = Array.map(records, (record) => record.targetPath);
33	    if (
34	      navigation.status !== "published" ||
35	      records.length !== targets.length ||
36	      HashSet.size(HashSet.fromIterable(recordTargets)) !== records.length ||
37	      !Array.every(targets, (target) => Array.contains(recordTargets, target))
